+    await waitFor(async()=>await evaluate(cdp,`(()=>{ const e=[...document.querySelectorAll('[data-native-node] .mapping-poc-ascii')].find(e=>e.textContent.includes('[created: From empty canvas]'));
+      const r=e?.getBoundingClientRect(), panel=document.querySelector('.window-panel').getBoundingClientRect();
+      return r && r.width>0 && r.right<panel.left && r.left>document.querySelector('.mapping-floating-pane').getBoundingClientRect().right && r.top>0 && r.bottom<innerHeight; })()`)).catch(async error => {
+      await captureScreenshot(cdp,{output:'/tmp/llm-visibility-failure.png'});
+      console.log('visibility',await evaluate(cdp,"[...document.querySelectorAll('[data-native-node] .mapping-poc-ascii')].map(e=>({text:e.textContent,rect:e.getBoundingClientRect().toJSON()}))")); throw error;
+    });
+    await captureScreenshot(cdp,{output:process.env.UI_SCREENSHOT_PATH ?? path.join(root,'create.png')});
+    console.log('PASS create on empty canvas');
+    await click('[aria-label="Close Workspace tools"]');
+    await key('z',2); await waitForSelector(cdp,'.mapping-empty-canvas');
+    console.log('PASS empty-canvas creation undo');
+    assert.deepEqual(browserErrors, [], 'No browser runtime exceptions');
+  });
+} finally {
+  if (server?.pid) { try { process.kill(-server.pid,'SIGTERM'); } catch {} }
+  await rm(root,{recursive:true,force:true});
+}

