import { expect, it } from 'vitest';
import { RevisionedDiagramService } from '../../../core/diagrams/diagramService';
import { diagramContentNodes } from '../../../core/diagrams/diagramContentNodes';
import { diagramSelectionItem, regionSelectionItem, selectionContentNodes, syncNativeDiagramSelection, type SelectionState } from '../selectionState';
import { toggleSubtreeSelection } from '../subtreeSelection';

const diagram = new RevisionedDiagramService().create({ id: 'tree', revision: 0,
  ascii: 'Root\n+-- Branch\n|   +-- Leaf\n|   `-- Peer\n`-- Sibling', structureKind: 'tree' }).diagram;
const nodes = diagramContentNodes(diagram.content);
const node = (label: string) => nodes.find(node => node.label === label)!;
const toggle = (state: SelectionState, label: string) => toggleSubtreeSelection(state, diagram, 'tree', node(label).id);
const selected = (state: SelectionState) => nodes.filter(node => state.items.some(item => item.displayNodeId === 'grid:tree'
  && selectionContentNodes(diagram, item.region).some(selected => selected.id === node.id))).map(node => node.label);

it('selects and deselects the complete subtree using canonical child relationships', () => {
  const state = toggle({ items: [] }, 'Branch');
  expect(selected(state)).toEqual(['Branch', 'Leaf', 'Peer']);
  expect(toggle(state, 'Branch').items).toEqual([]);
});

it('cuts a nested subtree from a larger selection while preserving its parent and sibling', () => {
  const all = toggle({ items: [] }, 'Root');
  const cut = toggle(all, 'Branch');
  expect(selected(cut)).toEqual(['Root', 'Sibling']);
  expect(selected(toggle(cut, 'Branch'))).toEqual(['Root', 'Branch', 'Leaf', 'Peer', 'Sibling']);
  const withoutLeaf = toggle(all, 'Leaf');
  expect(selected(withoutLeaf)).toEqual(['Root', 'Branch', 'Peer', 'Sibling']);
  expect(selected(toggle(withoutLeaf, 'Branch'))).toEqual(['Root', 'Sibling']);
});

it('subtracts from whole diagrams and every overlapping region without touching other instances', () => {
  const other = diagramSelectionItem('grid:other');
  const overlapping = regionSelectionItem(diagram, 'tree', { startLine: 3, endLine: 4, startColumn: 1, endColumn: 30 });
  const state = { items: [diagramSelectionItem('grid:tree'), overlapping, other] };
  const cut = toggle(state, 'Branch');
  expect(selected(cut)).toEqual(['Root', 'Sibling']);
  expect(cut.items).toContain(other);
  expect(cut.items.some(item => item.displayNodeId === 'grid:tree' && !item.region)).toBe(false);
  expect(toggle(cut, 'Root').items).toEqual([other]);
});

it('does not reinterpret saved regions from older content or unknown node IDs', () => {
  const saved = { ...regionSelectionItem(diagram, 'tree', { startLine: 1, endLine: 5, startColumn: 1, endColumn: 30 }), id: 'saved' };
  const stale = { ...saved, region: { ...saved.region!, sourceAscii: 'older content' } };
  const state = { items: [stale] };
  expect(toggle(state, 'Branch').items).toContain(stale);
  expect(toggleSubtreeSelection(state, diagram, 'tree', 'missing')).toBe(state);
});

it('keeps one envelope, identity and chronological position when removing interior or bottom branches', () => {
  const initial = toggle({ items: [diagramSelectionItem('grid:other')] }, 'Root');
  const cut = toggle(initial, 'Branch');
  expect(cut.items.map(item => item.id)).toEqual(initial.items.map(item => item.id));
  expect(cut.items[1].region!.rect).toEqual(initial.items[1].region!.rect);
  expect(cut.items[1].region!.contentNodeIds).toEqual([node('Root').id, node('Sibling').id]);
  const bottom = toggle(initial, 'Sibling');
  expect(bottom.items[1].id).toBe(initial.items[1].id);
  expect(bottom.items[1].region!.rect).toEqual(initial.items[1].region!.rect);
  expect(selected(bottom)).toEqual(['Root', 'Branch', 'Leaf', 'Peer']);
});

it('preserves node membership and its order when native whole-shape selection changes', () => {
  const region = toggle({ items: [] }, 'Branch').items[0];
  const initial = { items: [region, diagramSelectionItem('grid:other')] };
  const added = syncNativeDiagramSelection(initial, ['grid:tree', 'grid:other']);
  expect(added.items.slice(0, 2)).toEqual(initial.items);
  expect(syncNativeDiagramSelection(added, ['grid:other', 'grid:tree'])).toBe(added);
  expect(syncNativeDiagramSelection(added, []).items).toEqual([region]);
});

sources.domain/mapping/selection/canvasSelection:
import { selectionCommand, diagramSelectionItem, type SelectionCommand } from './selectionState';
import { flattenGrid, resolveScene, type ResolvedGridBox, type LineGridScene } from '../../core/diagrams/lineGrid';
import { diagramProjection, type DiagramViews } from '../workspace/diagramViewState';
import type { MappingCanvasState } from '../workspace/mappingWorkspace';
import type { MappingPocGridRect } from './mappingPoc';

export interface SelectionBounds { left: number; top: number; right: number; bottom: number }
export interface CanvasMarqueeSelection { diagramIds: string[]; regions: { boxId: string; rect: MappingPocGridRect }[] }

/** A whole diagram requires complete enclosure, including the boundary. */
export function enclosesDiagram(box: SelectionBounds, marquee: SelectionBounds): boolean {
  return marquee.left <= box.left && marquee.top <= box.top && marquee.right >= box.right && marquee.bottom >= box.bottom;
}

/** Canvas cell coordinates (fractional at the pointer), projected back to raw ASCII. */
export function selectCanvasMarquee(scene: LineGridScene, views: DiagramViews | undefined, bounds: SelectionBounds,
  promoted: readonly string[] = [], boxes: readonly ResolvedGridBox[] = flattenGrid(resolveScene(scene))): CanvasMarqueeSelection {
  const diagramIds = new Set(promoted), regions: CanvasMarqueeSelection['regions'] = [];
  for (const box of boxes) {
    if (box.box.kind !== 'diagram' || !box.contentId) continue;
    const { column: left, row: top, columns, rows } = box.bounds;
    const right = left + columns, bottom = top + rows, id = `grid:${box.box.id}`;
    if (enclosesDiagram({ left, top, right, bottom }, bounds)) diagramIds.add(id);
    if (diagramIds.has(id) || box.box.collapsed || bounds.right < left || bounds.bottom < top || bounds.left >= right || bounds.top >= bottom) continue;
    const projection = diagramProjection(scene, box.box.id, box.contentId, views);
    const firstRow = Math.max(0, Math.floor(bounds.top - top));
    const lastRow = Math.min(projection.sourceLines.length - 1, Math.floor(bounds.bottom - top));
    const startLine = projection.lineForRow(firstRow), endLine = projection.lineForRow(lastRow);
    if (startLine === undefined || endLine === undefined) continue;
    const rect = { startLine, endLine, startColumn: Math.max(1, Math.floor(bounds.left - left) + 1),
      endColumn: Math.min(columns, Math.floor(bounds.right - left) + 1) };
    // Do not silently include hidden source lines in an editable rectangle.
    if (projection.rect(rect)) regions.push({ boxId: box.box.id, rect });
  }
  return { diagramIds: [...diagramIds], regions };
}

/** Canvas integration keeps UI focus valid without giving it ownership of membership. */
export function updateSelection(state: MappingCanvasState, command: SelectionCommand): MappingCanvasState {
  const selection = selectionCommand(state.selection, command);
  const added = selection.items.filter(item => item.region && !state.selection.items.some(old => old.id === item.id)).at(-1);
  const focused = selection.items.find(item => item.region && item.id === state.controls.selectionFocusId);
  const nextFocus = added ?? focused ?? selection.items.filter(item => item.region).at(-1);
  return { ...state, selection, controls: nextFocus?.id === state.controls.selectionFocusId ? state.controls
    : { ...state.controls, selectionFocusId: nextFocus?.id ?? null, ...(nextFocus ? { activeBoxId: nextFocus.displayNodeId.slice(5) } : {}) } };
}

export function selectWholeDiagrams(state: MappingCanvasState, diagramIds: readonly string[]): MappingCanvasState {
  return updateSelection(state, { type: 'replace', items: diagramIds.map(diagramSelectionItem) });
}

export function deselectCanvas(state: MappingCanvasState): MappingCanvasState {
  return updateSelection(state, { type: 'clear' });
}

