import type { LineGridScene, ResolvedGridBox } from '../../core/diagrams/lineGrid';
import { diagramSelectionItem, regionSelectionItem } from './selectionState';
import { updateSelection, type CanvasMarqueeSelection } from './canvasSelection';
import type { SelectionPolicy } from './selectionGesture';
import { addDisplayNode, displayGeometry, type SelectionRegion } from '../workspace/displayModel';
import { initialSelectionSurface, type MappingCanvasState } from '../workspace/mappingWorkspace';

/** Commit membership and retain reusable region identities and their display surfaces. */
export function completeMarquee(current: MappingCanvasState, marquee: CanvasMarqueeSelection,
  scene: LineGridScene, boxes: readonly ResolvedGridBox[], policy: SelectionPolicy): MappingCanvasState {
  const items = marquee.diagramIds.map(diagramSelectionItem);
  for (const { boxId, rect } of marquee.regions) {
    if (marquee.diagramIds.includes(`grid:${boxId}`)) continue;
    const box = boxes.find(box => box.box.id === boxId), diagram = box?.contentId && scene.contents[box.contentId];
    if (!diagram) continue;
    const existing = Object.values(current.display.nodes).find((node): node is SelectionRegion => node.kind === 'selection'
      && node.sourceBoxId === boxId && node.sourceAscii === diagram.content.ascii
      && JSON.stringify(node.rect) === JSON.stringify(rect));
    items.push(regionSelectionItem(diagram, boxId, rect, existing?.id));
  }
  let next = updateSelection(current, { type: policy, items });
  const surfaces = { ...next.controls.surfaces };
  let last: SelectionRegion | undefined;
  for (const requested of items.filter(item => item.region)) {
    // The reducer may reuse an existing identity for a repeated gesture.
    const item = next.selection.items.find(item => item.region && item.displayNodeId === requested.displayNodeId
      && JSON.stringify(item.region.rect) === JSON.stringify(requested.region!.rect))!;
    const region = item.region!, existing = next.display.nodes[item.id];
    last = { ...displayGeometry(), id: item.id, kind: 'selection', childIds: [], expansion: 'expanded', displayMode: 'stacked',
      ...(existing?.kind === 'selection' ? existing : {}), sourceBoxId: item.displayNodeId.slice(5),
      sourceContentId: region.sourceContentId, sourceAscii: region.sourceAscii, sourceRevisionId: region.sourceRevisionId,
      rect: region.rect, contentNodeIds: region.contentNodeIds, selectedIds: [...region.selectedIds] };
    next = { ...next, display: existing ? { ...next.display, nodes: { ...next.display.nodes, [last.id]: last } }
      : addDisplayNode(next.display, last) };
    surfaces[last.id] = { ...surfaces[last.id] ?? initialSelectionSurface(), actionsOpen: false };
  }
  return { ...next, controls: { ...next.controls, surfaces, selectionFocusId: last?.id ?? null,
    ...(last ? { activeBoxId: last.sourceBoxId } : {}) } };
}

sources.domain/mapping/selection/importLegacySel:
import type { LineGridScene } from '../../core/diagrams/lineGrid';
import type { MappingCanvasState } from '../workspace/mappingWorkspace';
import type { SelectionRegion } from '../workspace/displayModel';
import type { MappingPocGridRect } from './mappingPoc';
import { diagramSelectionItem, regionSelectionItem, selectionCommand, type SelectionItem } from './selectionState';

/** Read old workspaces/checkpoints once. Runtime consumers never consult legacy membership fields. */
export function importLegacySelection(canvas: MappingCanvasState, scene: LineGridScene): MappingCanvasState {
  if (canvas.selection) return canvas;
  const legacy = canvas.controls as typeof canvas.controls & {
    selectedDiagramIds?: string[]; selectionRect?: MappingPocGridRect | null;
    selectedNodeIds?: string[]; retainedSelectionId?: string | null;
  };
  const { selectedDiagramIds, selectionRect, selectedNodeIds, retainedSelectionId, ...controls } = legacy;
  const items: SelectionItem[] = [];
  const nodes = Object.fromEntries(Object.entries(canvas.display.nodes).map(([id, node]) => {
    if (node.kind !== 'selection') return [id, node];
    const { selectionActive, ...context } = node as SelectionRegion & { selectionActive?: boolean };
    if (selectionActive !== false) items.push({ id, displayNodeId: `grid:${node.sourceBoxId}`, region: {
      sourceContentId: node.sourceContentId, sourceRevisionId: node.sourceRevisionId, sourceAscii: node.sourceAscii,
      rect: node.rect, selectedIds: node.selectedIds, ...(node.contentNodeIds ? { contentNodeIds: node.contentNodeIds } : {})
    } });
    return [id, context];
  }));
  let focusId = retainedSelectionId ?? null;
  if (selectionRect && !items.some(item => item.id === focusId)) {
    const find = (box: LineGridScene['root']): string | undefined => box.id === controls.activeBoxId && box.kind === 'diagram'
      ? box.contentId : box.kind === 'container' ? box.children.map(find).find(Boolean) : undefined;
    const contentId = find(scene.root), diagram = contentId && scene.contents[contentId];
    if (diagram) {
      const item = regionSelectionItem(diagram, controls.activeBoxId, selectionRect,
        `legacy-selection:${controls.activeBoxId}:${selectionRect.startLine}:${selectionRect.startColumn}:${selectionRect.endLine}:${selectionRect.endColumn}`);
      items.push({ ...item, region: { ...item.region!, selectedIds: selectedNodeIds ?? [] } }); focusId = item.id;
    }
  }
  const selection = selectionCommand({ items: [] }, { type: 'add', items: [...items, ...(selectedDiagramIds ?? []).map(diagramSelectionItem)] });
  return { ...canvas, display: { ...canvas.display, nodes }, selection,
    controls: { ...controls, selectionFocusId: selection.items.some(item => item.id === focusId) ? focusId : null } };
}

sources.domain/mapping/selection/selectionPresen:
import { addDisplayNode, displayGeometry, type SelectionRegion } from '../workspace/displayModel';
import { initialSelectionSurface, type MappingCanvasState } from '../workspace/mappingWorkspace';

/** Every state writer (including restore/API/history) gets the same selection presentation. */
export function syncSelectionPresentation(canvas: MappingCanvasState): MappingCanvasState {
  let display = canvas.display, surfaces = canvas.controls.surfaces;
  for (const item of canvas.selection.items) {
    if (!item.region) continue;
    const region = item.region, existing = display.nodes[item.id];
    const captured = { sourceBoxId: item.displayNodeId.slice(5), sourceContentId: region.sourceContentId,
      sourceAscii: region.sourceAscii, sourceRevisionId: region.sourceRevisionId, rect: region.rect,
      selectedIds: [...region.selectedIds], contentNodeIds: region.contentNodeIds };
    if (existing?.kind !== 'selection' || Object.entries(captured).some(([key, value]) =>
      JSON.stringify(existing[key as keyof SelectionRegion]) !== JSON.stringify(value))) {
      const node: SelectionRegion = { ...displayGeometry(), id: item.id, kind: 'selection', childIds: [],
        expansion: 'expanded', displayMode: 'stacked', ...(existing?.kind === 'selection' ? existing : {}), ...captured };
      display = existing ? { ...display, nodes: { ...display.nodes, [item.id]: node } } : addDisplayNode(display, node);
    }
    if (!surfaces[item.id]) surfaces = { ...surfaces, [item.id]: { ...initialSelectionSurface(), actionsOpen: false } };
  }
  return display === canvas.display && surfaces === canvas.controls.surfaces ? canvas : {
    ...canvas, display, controls: surfaces === canvas.controls.surfaces ? canvas.controls : { ...canvas.controls, surfaces }
  };
}

import { diagramContentNodes } from '../../core/diagrams/diagramContentNodes';
import type { DiagramContentNode } from '../../core/diagrams/diagramContent';
import type { Diagram } from '../../core/diagrams/diagram';
import { diagramSelectionNodes } from '../workspace/mappingDocument';
import type { MappingPocGridRect } from './mappingPoc';

export interface SelectionItem {
  readonly id: string;
  readonly displayNodeId: string;
  /** Absent means the entire diagram instance is selected. */
  readonly region?: {
    readonly sourceContentId: string;
    readonly sourceRevisionId?: string;
    readonly sourceAscii: string;
    /** Presentation envelope; never used to infer membership after capture. */
    readonly rect: MappingPocGridRect;
    /** Ordered canonical node membership. Absent only in legacy snapshots. */
    readonly contentNodeIds?: readonly string[];
    readonly selectedIds: readonly string[];
  };
}
/** Membership and insertion order only. Focus, panels and previews have separate lifetimes. */
export interface SelectionState { readonly items: readonly SelectionItem[] }
export type SelectionCommand =
  | { type: 'replace' | 'add'; items: readonly SelectionItem[] }
  | { type: 'toggleDiagram'; displayNodeId: string }
  | { type: 'remove'; id: string }
  | { type: 'clear' };

export const diagramSelectionItem = (displayNodeId: string): SelectionItem => ({ id: displayNodeId, displayNodeId });
export const selectedDiagramIds = (state: SelectionState): string[] => state.items.filter(item => !item.region).map(item => item.displayNodeId);
export const sameSelectionRegion = (a: SelectionItem, b: SelectionItem) => a.displayNodeId === b.displayNodeId && a.region && b.region
  && a.region.sourceContentId === b.region.sourceContentId && a.region.sourceAscii === b.region.sourceAscii
  && JSON.stringify(a.region.contentNodeIds) === JSON.stringify(b.region.contentNodeIds)
  && a.region.rect.startLine === b.region.rect.startLine && a.region.rect.endLine === b.region.rect.endLine
  && a.region.rect.startColumn === b.region.rect.startColumn && a.region.rect.endColumn === b.region.rect.endColumn;

/** One reducer enforces identity and deduplication across diagrams and regions for every consumer. */
export function selectionCommand(state: SelectionState, command: SelectionCommand): SelectionState {
  if (command.type === 'clear') return state.items.length ? { items: [] } : state;
  if (command.type === 'remove') return { items: state.items.filter(item => item.id !== command.id) };
  if (command.type === 'toggleDiagram') {
    const existing = state.items.find(item => !item.region && item.displayNodeId === command.displayNodeId);
    return selectionCommand(state, existing ? { type: 'remove', id: existing.id }
      : { type: 'add', items: [diagramSelectionItem(command.displayNodeId)] });
  }
  let items = command.type === 'replace' ? [] : [...state.items];
  for (const requested of command.items) {
    // Repeated gestures reuse the identity of the same captured region.
    const equivalent = requested.region && (items.find(item => sameSelectionRegion(item, requested)) ?? state.items.find(item => sameSelectionRegion(item, requested)));
    const item = equivalent ? { ...requested, id: equivalent.id } : requested;
    const index = items.findIndex(old => old.id === item.id);
    if (index < 0) items.push(item); else items[index] = item;
  }
  return { items };
}

/** Capture a completed region once, before rendering or publishing it. */
export function regionSelectionItem(diagram: Diagram, boxId: string, rect: MappingPocGridRect, id: string = crypto.randomUUID()): SelectionItem {
  return { id, displayNodeId: `grid:${boxId}`, region: {
    sourceContentId: diagram.id, sourceRevisionId: diagram.content.revisionId, sourceAscii: diagram.content.ascii, rect: { ...rect },
    contentNodeIds: diagramContentNodes(diagram.content).filter(node => nodeIntersectsRect(node, rect)).map(node => node.id),
    selectedIds: diagramSelectionNodes(diagram).filter(node => node.head.line >= rect.startLine && node.head.line <= rect.endLine
      && node.head.startColumn <= rect.endColumn && node.head.endColumn >= rect.startColumn).map(node => node.id)
  } };
}

export function nodeIntersectsRect(node: Pick<DiagramContentNode, 'line' | 'startColumn' | 'endColumn'>, rect: MappingPocGridRect): boolean {
  return node.line >= rect.startLine && node.line <= rect.endLine && node.startColumn <= rect.endColumn && node.endColumn >= rect.startColumn;
}

/** Legacy rectangles are read once as membership; current selections use explicit IDs. */
export function selectionContentNodes(diagram: Diagram, region?: SelectionItem['region']): readonly DiagramContentNode[] {
  const nodes = diagramContentNodes(diagram.content);
  if (!region) return nodes;
  if (region.sourceContentId !== diagram.id || region.sourceAscii !== diagram.content.ascii) return [];
  if (region.contentNodeIds === undefined) return nodes.filter(node => nodeIntersectsRect(node, region.rect));
  const byId = new Map(nodes.map(node => [node.id, node]));
  return region.contentNodeIds.flatMap(id => byId.has(id) ? [byId.get(id)!] : []);
}

/** Change membership without moving the envelope, changing identity, or reordering selections. */
export function withSelectionNodes(item: SelectionItem, diagram: Diagram, ids: readonly string[]): SelectionItem {
  const selected = new Set(ids), nodes = diagramContentNodes(diagram.content).filter(node => selected.has(node.id));
  const rect = item.region?.rect ?? {
    startLine: 1, endLine: diagram.content.ascii.split('\n').length, startColumn: 1,
    endColumn: Math.max(1, ...diagram.content.ascii.split('\n').map(line => line.length))
  };
  return { ...item, id: item.region ? item.id : crypto.randomUUID(), region: {
    sourceContentId: diagram.id, sourceRevisionId: diagram.content.revisionId, sourceAscii: diagram.content.ascii,
    rect, contentNodeIds: [...ids], selectedIds: diagramSelectionNodes(diagram).filter(mapping => nodes.some(node =>
      mapping.head.line === node.line && mapping.head.startColumn <= node.endColumn && mapping.head.endColumn >= node.startColumn)).map(mapping => mapping.id)
  } };
}

/** Native shape membership is one part of the selection, not a replacement for node selections. */
export function syncNativeDiagramSelection(state: SelectionState, selected: readonly string[]): SelectionState {
  const native = new Set(selected), existing = selectedDiagramIds(state);
  if (native.size === existing.length && existing.every(id => native.has(id))) return state;
  const items = state.items.filter(item => item.region || native.has(item.displayNodeId));
  const present = new Set(items.filter(item => !item.region).map(item => item.displayNodeId));
  return { items: [...items, ...[...native].filter(id => !present.has(id)).map(diagramSelectionItem)] };
}

sources.domain/mapping/selection/subtreeSelectio:
import type { Diagram } from '../../core/diagrams/diagram';
import { diagramContentNodes } from '../../core/diagrams/diagramContentNodes';
import { regionSelectionItem, selectionCommand, selectionContentNodes, withSelectionNodes, type SelectionItem, type SelectionState } from './selectionState';

/** The clicked root decides the direction; descendants always follow it, including folded ones. */
export function toggleSubtreeSelection(state: SelectionState, diagram: Diagram, boxId: string, nodeId: string): SelectionState {
  const nodes = diagramContentNodes(diagram.content);
  const byId = new Map(nodes.map(node => [node.id, node])), root = byId.get(nodeId);
  if (!root) return state;
  const subtree = new Set<string>();
  const visit = (id: string) => {
    if (subtree.has(id)) return;
    const node = byId.get(id); if (!node) return;
    subtree.add(id); node.childIds.forEach(visit);
  };
  visit(root.id);
  const current = (item: SelectionItem) => item.displayNodeId === `grid:${boxId}`
    && (!item.region || item.region.sourceContentId === diagram.id && item.region.sourceAscii === diagram.content.ascii);
  const selected = state.items.some(item => current(item) && selectionContentNodes(diagram, item.region).some(node => node.id === root.id));
  if (!selected) {
    const members = [...subtree].map(id => byId.get(id)!);
    const item = regionSelectionItem(diagram, boxId, {
      startLine: Math.min(...members.map(node => node.line)), endLine: Math.max(...members.map(node => node.line)),
      startColumn: Math.min(...members.map(node => node.startColumn)), endColumn: Math.max(...members.map(node => node.endColumn))
    });
    return selectionCommand(state, { type: 'add', items: [withSelectionNodes(item, diagram, [...subtree])] });
  }
  return { items: state.items.flatMap(item => {
    if (!current(item)) return [item];
    const members = selectionContentNodes(diagram, item.region);
    const remaining = members.filter(node => !subtree.has(node.id));
    if (remaining.length === members.length) return [item];
    return remaining.length ? [withSelectionNodes(item, diagram, remaining.map(node => node.id))] : [];
  }) };
}

sources.domain/mapping/workspace/__tests__/delet:
import { expect, it } from 'vitest';
import { MappingDocumentController } from '../mappingDocumentController';
import { mappingDocumentFromScene } from '../mappingDocument';
import { singleDiagramScene } from '../../../core/diagrams/projectDiagramCanvas';
import { initialCanvasState } from '../mappingWorkspace';
import { displayGeometry } from '../displayModel';
import { diagramSelectionItem, regionSelectionItem } from '../../selection/selectionState';
import { defaultArrowAppearance } from '../../../core/diagrams/diagramConnection';
import { diagramContentNodes } from '../../../core/diagrams/diagramContentNodes';

const setup = () => new MappingDocumentController(mappingDocumentFromScene(singleDiagramScene('Root\n`-- Child')), initialCanvasState());
it('deletes selected diagrams, incident edges, selection and owned panes in one undo step', () => {
  const controller = setup();
  controller.applyUpdate(0, [{ method: 'diagram-create', id: 'other', ascii: 'Other' }]);
  const diagram = controller.getSnapshot().document.scene.contents.overview;
  controller.applyUpdate(1, [{ method: 'edge-create', edge: { id: 'link', source: {
    kind: 'content-node', displayNodeId: 'grid:overview', revisionId: diagram.content.revisionId,
    contentNodeId: diagramContentNodes(diagram.content)[0].id, side: 'auto'
  }, target: { kind: 'box', displayNodeId: 'grid:other', side: 'auto' }, appearance: defaultArrowAppearance } }]);
  controller.updateCanvas(canvas => ({ ...canvas, display: { rootIds: ['selection'], nodes: {
    selection: { ...displayGeometry(), id: 'selection', kind: 'selection', sourceBoxId: 'overview', sourceContentId: diagram.id,
      sourceAscii: diagram.content.ascii, rect: { startLine: 1, endLine: 1, startColumn: 1, endColumn: 4 }, selectedIds: [],
      childIds: ['pane'], expansion: 'expanded', displayMode: 'stacked' },
    pane: { ...displayGeometry(), id: 'pane', kind: 'detail', title: 'Captured context', ascii: 'Context', childIds: [], expansion: 'expanded' }
  } } }), true);
  const other = controller.getSnapshot().document.scene.contents.other;
  controller.select({ type: 'replace', items: [diagramSelectionItem('grid:overview'),
    regionSelectionItem(other, 'other', { startLine: 1, endLine: 1, startColumn: 1, endColumn: 5 })] });
  const before = controller.getSnapshot();
  controller.applyUpdate(before.version, [{ method: 'delete-diagrams', nodeIds: ['grid:overview'] }]);
  const after = controller.getSnapshot();
  expect(after.version).toBe(before.version + 1);
  expect(after.document.edges).toEqual([]);
  expect(after.document.scene.contents.overview).toBeUndefined();
  const remaining = after.canvas.selection.items[0];
  expect(after.canvas.display.rootIds).toEqual([remaining.id]);
  expect(after.canvas.display.nodes[remaining.id]).toMatchObject({ kind: 'selection', sourceBoxId: 'other' });
  expect(after.canvas.display.nodes.selection).toBeUndefined();
  expect(after.canvas.display.nodes.pane).toBeUndefined();
  expect(after.canvas.selection.items.map(item => item.displayNodeId)).toEqual(['grid:other']);
  controller.undo();
  expect(controller.getSnapshot().document).toEqual(before.document);
  expect(controller.getSnapshot().canvas).toEqual(before.canvas);
  controller.undo(true);
  expect(controller.getSnapshot().document).toEqual(after.document);
});

it('deletes all diagrams, supports an empty canvas, and restores the group together', () => {
  const controller = setup();
  controller.applyUpdate(0, [{ method: 'diagram-create', id: 'other', ascii: 'Other' }]);
  const before = controller.getSnapshot();
  controller.applyUpdate(before.version, [{ method: 'delete-diagrams', nodeIds: ['grid:overview', 'grid:other'] }]);
  expect(controller.nodes().filter(node => node.kind === 'diagram')).toEqual([]);
  expect(controller.getSnapshot().document.scene.contents).toEqual({});
  controller.undo();
  expect(controller.getSnapshot().document).toEqual(before.document);
  controller.undo(true);
  controller.applyUpdate(controller.getSnapshot().version, [{ method: 'diagram-create', id: 'new', ascii: 'New' }]);
  expect(controller.nodes().some(node => node.id === 'grid:new')).toBe(true);
});

it('rejects stale or invalid selections atomically and allows deleting a root diagram', () => {
  const controller = setup(), before = controller.getSnapshot();
  expect(() => controller.applyUpdate(100, [{ method: 'delete-diagrams', nodeIds: ['grid:overview'] }])).toThrow('VERSION_CONFLICT');
  for (const nodeIds of [[], ['grid:root'], ['grid:overview', 'grid:missing']]) {
    expect(() => controller.applyUpdate(0, [{ method: 'delete-diagrams', nodeIds }])).toThrow();
    expect(controller.getSnapshot()).toBe(before);
  }
  const scene = before.document.scene;
  if (scene.root.kind !== 'container') throw Error();
  const root = new MappingDocumentController(mappingDocumentFromScene({ ...scene, root: scene.root.children[0] }), initialCanvasState());
  root.applyUpdate(0, [{ method: 'delete-diagrams', nodeIds: ['grid:overview'] }]);
  expect(root.getSnapshot().document.scene.root).toMatchObject({ kind: 'container', children: [] });
  root.undo();
  expect(root.getSnapshot().document.scene.root.kind).toBe('diagram');
});

